begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('f1000000-0000-4000-8000-000000000001');
insert into profiles(id,display_name,consented_at,timezone) values('f1000000-0000-4000-8000-000000000001','Reminder test',now(),'UTC');
insert into families(id,name) values('f2000000-0000-4000-8000-000000000001','Reminder test');
insert into family_members(family_id,user_id,role) values('f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','owner');
insert into children(id,family_id,name,sex,birth_date) values('f3000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','Reminder test','female',current_date);
delete from feeding_push_config;
insert into feeding_push_config(public_key,worker_url,token_secret_id) values(repeat('B',87),'https://example.invalid',(select vault.create_secret(repeat('d',64),'yesterday-test-'||gen_random_uuid())));
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select save_feeding_reminder('yesterday',180,false,jsonb_build_object('endpoint','https://fcm.googleapis.com/fcm/send/yesterday-test','keys',jsonb_build_object('p256dh',repeat('B',87),'auth',repeat('A',22))),'ko')$$,'one atomic action saves yesterday mode and device');
select is((select feeding_reference from notification_preferences where user_id=auth.uid()),'yesterday','yesterday mode persists');
select throws_ok($$select save_feeding_reminder('both',180,false)$$,'22023','invalid mode','simultaneous reminder modes are rejected');
select throws_ok($$select save_feeding_reminder('interval',180,false,jsonb_build_object('endpoint','https://127.0.0.1/private','keys',jsonb_build_object('p256dh',repeat('B',87),'auth',repeat('A',22))),'ko')$$,'23514',null,'invalid registration cannot switch the mode');
select is((select feeding_reference from notification_preferences where user_id=auth.uid()),'yesterday','registration failure rolls back all preferences');
reset role;
update web_push_subscriptions set created_at=now()-interval '2 days' where user_id='f1000000-0000-4000-8000-000000000001';
insert into care_records(id,child_id,kind,started_at,record_timezone,created_by,updated_by) values('f4000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','formula',date_trunc('minute',now() at time zone 'UTC') at time zone 'UTC'-interval '1 day','UTC','f1000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001');
select is((select count(*)::int from feeding_push_candidates()),1,'yesterday formula schedules at the same local minute');
select is((select scheduled_at from feeding_push_candidates()),date_trunc('minute',now() at time zone 'UTC') at time zone 'UTC','scheduled time uses the user local clock');
create temporary table yesterday_claim as select * from claim_feeding_push(repeat('d',64));
select is((select reference from yesterday_claim),'yesterday','worker receives the selected reference');
select is((select meal_kind from yesterday_claim),'formula','worker receives the meal type without a baby name or amount');
select ok((select validate_feeding_push(id,lease_token) from yesterday_claim),'yesterday lease is valid before delivery');
select is((select count(*)::int from claim_feeding_push(repeat('d',64))),0,'a second worker cannot lease the same source');
-- A feed entered while a notification is queued cancels it before sending.
insert into care_records(id,child_id,kind,started_at,record_timezone,created_by,updated_by) values('f4000000-0000-4000-8000-000000000002','f3000000-0000-4000-8000-000000000001','solids',now()-interval '20 minutes','UTC','f1000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001');
select ok(not (select validate_feeding_push(id,lease_token) from yesterday_claim),'recent feeding invalidates an already queued reminder');
select is((select count(*)::int from feeding_push_candidates()),0,'a feed in the previous 90 minutes suppresses yesterday reminders');
delete from care_records where id='f4000000-0000-4000-8000-000000000002';
update notification_preferences set feeding_reference='interval';
select ok(not (select validate_feeding_push(id,lease_token) from yesterday_claim),'switching mode invalidates yesterday deliveries');
select is((select count(*)::int from feeding_push_candidates()),0,'interval mode never also schedules yesterday reminders');
update notification_preferences set feeding_reference='yesterday',feeding_enabled=false;
select is((select count(*)::int from feeding_push_candidates()),0,'off suppresses yesterday reminders');
update notification_preferences set feeding_enabled=true,quiet_start=(now() at time zone 'UTC'-interval '30 minutes')::time,quiet_end=(now() at time zone 'UTC'+interval '30 minutes')::time;
select is((select count(*)::int from feeding_push_candidates()),0,'quiet hours also suppress yesterday reminders');
update notification_preferences set quiet_start='00:00',quiet_end='00:00';
select finish_feeding_push(id,lease_token,'sent') from yesterday_claim;
select is((select count(*)::int from feeding_push_candidates()),0,'a sent reminder prevents clustered reminders for one hour');
select is((select count(*)::int from claim_feeding_push(repeat('d',64))),0,'successful yesterday delivery is not repeated');
update feeding_push_deliveries set sent_at=now()-interval '61 minutes';
select is((select count(*)::int from claim_feeding_push(repeat('d',64))),0,'same yesterday record cannot be delivered twice after the cooldown');
update care_records set started_at=started_at-interval '2 days' where id='f4000000-0000-4000-8000-000000000001';
select is((select count(*)::int from feeding_push_candidates()),0,'records older than yesterday never generate backfill');
update care_records set started_at=date_trunc('minute',now() at time zone 'UTC') at time zone 'UTC'-interval '1 day',kind='breast',ended_at=null where id='f4000000-0000-4000-8000-000000000001';
select is((select count(*)::int from feeding_push_candidates()),0,'an unfinished breastfeed is not a yesterday reference');
update care_records set ended_at=started_at+interval '10 minutes' where id='f4000000-0000-4000-8000-000000000001';
select is((select count(*)::int from feeding_push_candidates()),1,'a completed breastfeed is a valid yesterday reference');
insert into care_records(id,child_id,kind,started_at,record_timezone,created_by,updated_by) select 'f4000000-0000-4000-8000-000000000003',child_id,'solids',started_at,record_timezone,created_by,updated_by from care_records where id='f4000000-0000-4000-8000-000000000001';
select is((select count(*)::int from feeding_push_candidates()),1,'clustered yesterday meals yield at most one reminder per child and device');
update profiles set timezone='Asia/Kolkata' where id='f1000000-0000-4000-8000-000000000001';
select is((select count(*)::int from feeding_push_candidates()),1,'half-hour local time zones preserve yesterday scheduling');
select is(feeding_reference_time('2026-03-07 08:30+00','America/New_York'),'2026-03-08 07:30+00'::timestamptz,'spring DST keeps 03:30 local with a 23-hour offset');
select is(feeding_reference_time('2026-10-31 08:30+00','America/New_York'),'2026-11-01 09:30+00'::timestamptz,'fall DST keeps 04:30 local with a 25-hour offset');
select is(feeding_reference_time('2026-03-07 07:30+00','America/New_York'),null::timestamptz,'a nonexistent spring 02:30 is skipped instead of shifted');
select is(feeding_reference_time('2026-10-28 20:00+00','Asia/Kolkata'),'2026-10-29 20:00+00'::timestamptz,'half-hour zone supports a date change at local midnight');
select ok(not has_function_privilege('anon','public.save_feeding_reminder(text,integer,boolean,jsonb,text)','execute'),'anonymous users cannot change reminder modes');
select * from finish();
rollback;
